async def execute(limit=20):
    import json
    cfg = env['ai.zabbix.config'].search([('active', '=', True)], limit=1)
    if not cfg:
        return json.dumps({"error": "Zabbix är inte konfigurerat. Skapa ai.zabbix.config med URL + API-token (Settings → Technical → AI Orkestrering)."})
    try:
        return json.dumps(cfg._zabbix_problems(limit=limit), indent=2, default=str)
    except Exception as e:
        return json.dumps({"error": f"Zabbix-fel: {e}"})

