async def execute(title="", content="", source_ref=""):
    import json
    coworker = env['ai.coworker'].search([('name', '=', 'Zabbix Analyst')], limit=1)
    if not coworker:
        return json.dumps({"error": "Zabbix Analyst-coworkern finns inte."})
    try:
        concept_key = f"zabbix-infra-{title.strip().lower().replace(' ', '-')[:80]}"
        concept = env['ai.okf.concept'].sudo()._okf_upsert(
            artifact_type='zabbix-infrastructure',
            concept_key=concept_key,
            title=title.strip(),
            summary=content.strip(),
            source_ref=source_ref or f'ai.coworker,{coworker.id}',
            attribution=[{"line": 1, "source_ref": source_ref or f'ai.coworker,{coworker.id}'}],
            owner_coworker_id=coworker.id,
            generated_by='ai',
            status='stable',
        )
        return json.dumps({"ok": True, "concept_id": concept.id, "concept_key": concept_key, "version": concept.version})
    except Exception as e:
        return json.dumps({"error": f"Kunde inte spara minne: {e}"})
